'use client'
import { useCallback, useEffect, useState } from 'react'
import { createClient } from '@/utils/supabase/client'
import { type User } from '@supabase/supabase-js'
import Avatar from './avatar'

export default function AccountForm({ user }: { user: User | null }) {
    const supabase = createClient()
    const [loading, setLoading] = useState(true)
    const [fullname, setFullname] = useState<string | null>(null)
    const [username, setUsername] = useState<string | null>(null)
    const [website, setWebsite] = useState<string | null>(null)
    const [avatar_url, setAvatarUrl] = useState<string | null>(null)

    const getProfile = useCallback(async () => {
        try {
            setLoading(true)

            const { data, error, status } = await supabase
                .from('profiles')
                .select(`full_name, username, website, avatar_url`)
                .eq('id', user?.id)
                .single()

            if (error && status !== 406) {
                console.log(error)
                throw error
            }

            if (data) {
                setFullname(data.full_name)
                setUsername(data.username)
                setWebsite(data.website)
                setAvatarUrl(data.avatar_url)
            }
        } catch (error) {
            alert('Error loading user data!')
        } finally {
            setLoading(false)
        }
    }, [user, supabase])

    useEffect(() => {
        getProfile()
    }, [user, getProfile])

    async function updateProfile({
        username,
        website,
        avatar_url,
    }: {
        username: string | null
        fullname: string | null
        website: string | null
        avatar_url: string | null
    }) {
        try {
            setLoading(true)

            const { error } = await supabase.from('profiles').upsert({
                id: user?.id as string,
                full_name: fullname,
                username,
                website,
                avatar_url,
                updated_at: new Date().toISOString(),
            })
            if (error) throw error
            alert('Profile updated!')
        } catch (error) {
            const msg = (error as any)?.message ?? JSON.stringify(error)
            console.error('profiles upsert error:', error)
            alert(`Error updating the data: ${msg}`)
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="surface mx-auto flex w-full max-w-xl flex-col gap-8 rounded-[calc(var(--radius)+1rem)] border border-border/40 bg-card/70 p-8 shadow-card">
            <div className="flex flex-col items-center gap-4 text-center">
                <Avatar
                    uid={user?.id ?? null}
                    url={avatar_url}
                    size={150}
                    onUpload={(url) => {
                        setAvatarUrl(url)
                        updateProfile({ fullname, username, website, avatar_url: url })
                    }}
                />
                <div className="space-y-1">
                    <p className="text-sm font-medium uppercase tracking-[0.32em] text-muted/80">Account</p>
                    <h2 className="text-2xl font-semibold text-fg">Profile preferences</h2>
                    <p className="text-sm text-muted">
                        Update your public information and avatar. Changes are saved instantly after upload.
                    </p>
                </div>
            </div>

            <div className="grid gap-5">
                <label className="grid gap-2" htmlFor="email">
                    <span className="text-xs font-semibold uppercase tracking-[0.32em] text-muted">Email</span>
                    <input
                        id="email"
                        type="text"
                        value={user?.email ?? ''}
                        disabled
                        className="w-full rounded-2xl border border-border/40 bg-card/40 px-4 py-3 text-sm text-muted/90 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)]"
                    />
                </label>

                <label className="grid gap-2" htmlFor="fullName">
                    <span className="text-xs font-semibold uppercase tracking-[0.32em] text-muted">Full name</span>
                    <input
                        id="fullName"
                        type="text"
                        value={fullname || ''}
                        onChange={(e) => setFullname(e.target.value)}
                        className="w-full rounded-2xl border border-border/40 bg-transparent px-4 py-3 text-sm text-fg transition focus:border-primary/50 focus:bg-card/70 focus:ring-2 focus:ring-primary/30"
                    />
                </label>

                <label className="grid gap-2" htmlFor="username">
                    <span className="text-xs font-semibold uppercase tracking-[0.32em] text-muted">Username</span>
                    <input
                        id="username"
                        type="text"
                        value={username || ''}
                        onChange={(e) => setUsername(e.target.value)}
                        className="w-full rounded-2xl border border-border/40 bg-transparent px-4 py-3 text-sm text-fg transition focus:border-primary/50 focus:bg-card/70 focus:ring-2 focus:ring-primary/30"
                    />
                </label>

                <label className="grid gap-2" htmlFor="website">
                    <span className="text-xs font-semibold uppercase tracking-[0.32em] text-muted">Website</span>
                    <input
                        id="website"
                        type="url"
                        value={website || ''}
                        onChange={(e) => setWebsite(e.target.value)}
                        className="w-full rounded-2xl border border-border/40 bg-transparent px-4 py-3 text-sm text-fg transition focus:border-primary/50 focus:bg-card/70 focus:ring-2 focus:ring-primary/30"
                    />
                </label>
            </div>

            <div className="flex flex-col gap-3 pt-2 sm:flex-row sm:items-center sm:justify-between">
                <button
                    className="inline-flex items-center justify-center rounded-full border border-primary/60 bg-primary px-6 py-3 text-sm font-semibold text-primaryfg shadow-[0_24px_60px_-32px_rgba(252,50,114,0.7)] transition hover:-translate-y-[1px] hover:shadow-[0_32px_72px_-34px_rgba(252,50,114,0.82)]"
                    onClick={() => updateProfile({ fullname, username, website, avatar_url })}
                    disabled={loading}
                >
                    {loading ? 'Loading ...' : 'Update profile'}
                </button>

                <form action="/auth/signout" method="post" className="w-full sm:w-auto">
                    <button
                        className="inline-flex w-full items-center justify-center rounded-full border border-border/50 bg-transparent px-6 py-3 text-sm font-medium text-muted transition hover:border-border/70 hover:bg-card/40 hover:text-fg"
                        type="submit"
                    >
                        Sign out
                    </button>
                </form>
            </div>
        </div>
    )
}

'use client'
import React, { useEffect, useState } from 'react'
import { createClient } from '@/utils/supabase/client'
import Image from 'next/image'

const clampSize = (value: number) => {
  if (!Number.isFinite(value)) {
    return 0
  }
  const rounded = Math.round(value)
  if (rounded < 0) {
    return 0
  }
  if (rounded > 512) {
    return 512
  }
  return rounded
}

export default function Avatar({
  uid,
  url,
  size,
  onUpload,
}: {
  uid: string | null
  url: string | null
  size: number
  onUpload: (url: string) => void
}) {
  const supabase = createClient()
  const [avatarUrl, setAvatarUrl] = useState<string | null>(url)
  const [uploading, setUploading] = useState(false)

  useEffect(() => {
    async function downloadImage(path: string) {
      try {
        const { data, error } = await supabase.storage.from('avatars').download(path)
        if (error) {
          throw error
        }

        const url = URL.createObjectURL(data)
        setAvatarUrl(url)
      } catch (error) {
        console.log('Error downloading image: ', error)
      }
    }

    if (url) downloadImage(url)
  }, [url, supabase])

  const uploadAvatar: React.ChangeEventHandler<HTMLInputElement> = async (event) => {
    try {
      setUploading(true)

      if (!event.target.files || event.target.files.length === 0) {
        throw new Error('You must select an image to upload.')
      }

      const file = event.target.files[0]
      const fileExt = file.name.split('.').pop()
      const filePath = `${uid}-${Math.random()}.${fileExt}`

      const { error: uploadError } = await supabase.storage.from('avatars').upload(filePath, file)

      if (uploadError) {
        throw uploadError
      }

      onUpload(filePath)
    } catch (error) {
      alert('Error uploading avatar!')
    } finally {
      setUploading(false)
    }
  }

  const clampedSize = clampSize(size)
  const avatarSizeClass = `size-px-${clampedSize}`
  const widthClass = `w-px-${clampedSize}`

  return (
    <div>
      {avatarUrl ? (
        <Image
          width={size}
          height={size}
          src={avatarUrl}
          alt="Avatar"
          className={`rounded-full border border-border/60 bg-card/60 object-cover shadow-[0_28px_68px_-36px_rgba(6,18,34,0.82)] ${avatarSizeClass}`}
        />
      ) : (
        <div
          className={`flex items-center justify-center rounded-full border border-dashed border-border/50 bg-card/40 text-sm font-medium text-muted ${avatarSizeClass}`}
        >
          No image
        </div>
      )}
      <div className={`mt-4 flex flex-col items-center ${widthClass} max-w-full`}>
        <label
          className="inline-flex w-full max-w-xs items-center justify-center rounded-full border border-primary/50 bg-primary px-6 py-3 text-sm font-semibold text-primaryfg shadow-[0_24px_58px_-32px_rgba(252,50,114,0.7)] transition hover:-translate-y-[1px] hover:shadow-[0_30px_72px_-32px_rgba(252,50,114,0.82)]"
          htmlFor="single"
        >
          {uploading ? 'Uploading ...' : 'Upload'}
        </label>
        <input
          className="hidden"
          type="file"
          id="single"
          accept="image/*"
          onChange={uploadAvatar}
          disabled={uploading}
        />
      </div>
    </div>
  )
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";

import Section from "@ui/components/common/section";
import Card from "@ui/components/common/card";
import Skeleton from "@ui/components/common/skeleton";
import Input from "@ui/components/common/input";
import Button from "@ui/components/common/button";
import StatusBadge from "@ui/components/admin/StatusBadge";
import { toast } from "@ui/components/common/toast";
import { supabase } from "@shared/lib/supabase";
import { getValidAccessToken } from "@shared/lib/auth";
import { useDebounce } from "@shared/hooks/useDebounce";

const DEFAULT_ADMIN_TOKEN =
  process.env.NEXT_PUBLIC_ADMIN_TOKEN ?? process.env.VITE_ADMIN_TOKEN ?? "";

interface Payment {
  id: string;
  status: string;
  amount: number;
  currency: string | null;
  created_at: string;
}

interface OrderRow {
  id: string;
  created_at: string;
  amount_total: number;
  currency: string;
  status: string;
  payment_status: string | null;
  payment: Payment | null;
}

interface Summary {
  total: number;
  pending: number;
  processing: number;
  succeeded: number;
  failed: number;
  cancelled: number;
  average_check: number;
  failed_share: number;
  conversion: number;
}

function useAdminToken() {
  const [token, setToken] = useState("");

  useEffect(() => {
    let initial = DEFAULT_ADMIN_TOKEN ?? "";
    try {
      const stored = window.localStorage.getItem("admin:token");
      if (stored) initial = stored;
    } catch {
      // ignore storage errors
    }
    setToken(initial);
  }, []);

  const update = (value: string) => {
    setToken(value);
    try {
      window.localStorage.setItem("admin:token", value);
    } catch {
      // ignore storage errors
    }
  };

  return { token, setToken: update };
}

async function authorizedRequest(path: string, adminToken: string, init?: RequestInit) {
  const accessToken = await getValidAccessToken();
  if (!accessToken) throw new Error("Not authenticated");

  const headers = new Headers(init?.headers ?? {});
  headers.set("accept", "application/json");
  headers.set("Authorization", `Bearer ${accessToken}`);
  if (adminToken) headers.set("x-admin-token", adminToken);

  // ensure absolute URL to avoid relative-path resolution issues
  const url = path.startsWith("http") ? path : new URL(path, window.location.origin).toString();

  return fetch(url, { ...init, headers, cache: "no-store" });
}

async function fetchSummary(adminToken: string): Promise<Summary | null> {
  // Попытка через авторизованный запрос (если есть access token)
  try {
    const response = await authorizedRequest("/api/admin/orders?days=30", adminToken);
    if (response.ok) {
      const json = (await response.json()) as Summary & { ok?: boolean };
      if (json?.ok === false) return null;
      return json;
    }
    // если 404/500 — упадём в fallback ниже
  } catch (err) {
    console.warn("authorizedRequest failed for summary, will try fallback:", err);
  }

  // Fallback: прямой fetch с использованием только x-admin-token (если сервер принимает)
  try {
    const url = new URL("/api/admin/orders?days=30", window.location.origin).toString();
    const headers: Record<string, string> = { accept: "application/json" };
    if (adminToken) headers["x-admin-token"] = adminToken;
    const res = await fetch(url, { headers, cache: "no-store" });
    if (!res.ok) return null;
    const json = (await res.json()) as Summary & { ok?: boolean };
    if (json?.ok === false) return null;
    return json;
  } catch (error) {
    console.warn("fetchSummary fallback failed", error);
    return null;
  }
}

interface OrdersQueryParams {
  page: number;
  pageSize: number;
  status?: string;
  q?: string;
  from?: string;
  to?: string;
}

async function fetchOrders(params: OrdersQueryParams, adminToken: string) {
  const url = new URL("/api/admin/orders", window.location.origin);
  url.searchParams.set("page", String(params.page));
  url.searchParams.set("pageSize", String(params.pageSize));
  if (params.status && params.status !== "all") {
    url.searchParams.set("status", params.status);
  }
  if (params.q) url.searchParams.set("q", params.q);
  if (params.from) url.searchParams.set("from", params.from);
  if (params.to) url.searchParams.set("to", params.to);

  const response = await authorizedRequest(url.toString(), adminToken);
  if (!response.ok) {
    throw new Error(await response.text());
  }
  const json = await response.json();
  if (json?.ok === false) {
    throw new Error(String(json?.message || json?.error || "Failed to load orders"));
  }
  return {
    items: (Array.isArray(json?.items) ? json.items : []) as OrderRow[],
    count: Number(json?.count || 0),
  };
}

async function callPayments(path: string, body: unknown, adminToken: string) {
  // primary attempt via authorizedRequest
  try {
    const response = await authorizedRequest(`/api/payments${path}`, adminToken, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body ?? {}),
    });

    if (response.status === 404) {
      // try fallback endpoints if primary not found
      const fallbackPaths = [`/api/admin/payments${path}`, `/.netlify/functions/payments${path}`];
      for (const p of fallbackPaths) {
        try {
          const accessToken = await getValidAccessToken().catch(() => "");
          const headers: Record<string, string> = {
            accept: "application/json",
            "content-type": "application/json",
          };
          if (accessToken) headers.Authorization = `Bearer ${accessToken}`;
          if (adminToken) headers["x-admin-token"] = adminToken;

          const url = new URL(p, window.location.origin).toString();
          const res = await fetch(url, {
            method: "POST",
            headers,
            body: JSON.stringify(body ?? {}),
            cache: "no-store",
          });
          if (res.ok) return res.json();
          // if non-404 failure, continue to next fallback
          if (res.status !== 404) {
            const text = await res.text().catch(() => String(res.status));
            throw new Error(`payments ${p} ${res.status} - ${text}`);
          }
        } catch {
          // try next fallback
        }
      }
      throw new Error(`payments ${path} 404`);
    }

    if (!response.ok) {
      throw new Error(`payments ${path} ${response.status}`);
    }
    return response.json();
  } catch (err) {
    // bubble up error
    throw err;
  }
}

function formatCurrency(amount: number, currency: string | null | undefined) {
  const cur = (currency || "EUR").toUpperCase();
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency: cur,
    }).format(amount);
  } catch {
    return `${amount.toFixed(2)} ${cur}`;
  }
}

const STATUS_OPTIONS = [
  { value: "all", label: "All statuses" },
  { value: "pending", label: "Pending" },
  { value: "processing", label: "Processing" },
  { value: "succeeded", label: "Succeeded" },
  { value: "failed", label: "Failed" },
  { value: "cancelled", label: "Cancelled" },
];

const PAGE_SIZE = 25;

export function OrdersClient() {
  const { token, setToken } = useAdminToken();

  const [orders, setOrders] = useState<OrderRow[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [total, setTotal] = useState(0);

  const [status, setStatus] = useState("all");
  const [search, setSearch] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [page, setPage] = useState(1);
  const [refreshToken, setRefreshToken] = useState(0);

  const debouncedSearch = useDebounce(search, 400);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  useEffect(() => {
    setPage(1);
  }, [debouncedSearch, status, from, to]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const data = await fetchSummary(token);
      if (!cancelled) setSummary(data);
    })();
    return () => {
      cancelled = true;
    };
  }, [token, refreshToken]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const { items, count } = await fetchOrders(
          {
            page,
            pageSize: PAGE_SIZE,
            status,
            q: debouncedSearch ? debouncedSearch : undefined,
            from: from || undefined,
            to: to || undefined,
          },
          token,
        );
        if (!cancelled) {
          setOrders(items);
          setTotal(count);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : String(err));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [page, status, debouncedSearch, from, to, token, refreshToken]);

  const summaryCards = useMemo(() => {
    if (!summary) return null;
    return [
      { label: "Orders", value: summary.total.toLocaleString() },
      { label: "Conversion", value: `${summary.conversion.toFixed(2)}%` },
      { label: "Average check", value: formatCurrency(summary.average_check, "EUR") },
      { label: "Failed share", value: `${summary.failed_share.toFixed(2)}%` },
    ];
  }, [summary]);

  const clearFilters = () => {
    setSearch("");
    setStatus("all");
    setFrom("");
    setTo("");
  };

  const handleRefresh = () => setRefreshToken((value) => value + 1);

  return (
    <Section className="space-y-6 p-6">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="text-2xl font-semibold">Orders</h1>
        <div className="ml-auto flex flex-wrap items-center gap-3 text-sm">
          <label className="text-muted-foreground" htmlFor="admin-token-input">
            Admin token
          </label>
          <Input
            id="admin-token-input"
            value={token}
            onChange={(event) => setToken(event.currentTarget.value)}
            placeholder="x-admin-token"
            className="h-9 w-64"
          />
          <Button variant="ghost" className="h-9" onClick={handleRefresh}>
            Refresh
          </Button>
        </div>
      </div>

      <Card className="p-4">
        <div className="grid gap-3 md:grid-cols-[minmax(0,1fr)_160px_140px_140px]">
          <Input
            value={search}
            onChange={(event) => setSearch(event.currentTarget.value)}
            placeholder="Search by order id..."
          />
          <select
            className="h-10 rounded-md border border-border bg-background px-3 text-sm"
            value={status}
            onChange={(event) => setStatus(event.currentTarget.value)}
          >
            {STATUS_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
          <Input type="date" value={from} onChange={(event) => setFrom(event.currentTarget.value)} />
          <Input type="date" value={to} onChange={(event) => setTo(event.currentTarget.value)} />
        </div>
        <div className="mt-3 flex items-center justify-end gap-2 text-xs text-muted-foreground">
          <Button variant="ghost" className="h-8 px-3" onClick={clearFilters}>
            Clear filters
          </Button>
        </div>
      </Card>

      {summaryCards ? (
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {summaryCards.map((card) => (
            <Card key={card.label} className="p-4">
              <div className="text-sm text-muted-foreground">{card.label}</div>
              <div className="text-xl font-semibold">{card.value}</div>
            </Card>
          ))}
        </div>
      ) : null}

      {loading ? (
        <div className="space-y-2">
          <Skeleton className="h-6 w-1/3" />
          <Skeleton className="h-6 w-1/2" />
          <Skeleton className="h-6 w-2/3" />
        </div>
      ) : error ? (
        <div className="text-sm text-rose-500">{error}</div>
      ) : orders.length === 0 ? (
        <div className="text-sm text-muted-foreground">No orders.</div>
      ) : (
        <div className="space-y-4">
          <div className="overflow-x-auto">
            <table className="min-w-full border-collapse text-sm">
              <thead>
                <tr className="border-b border-border/40 text-left text-xs uppercase tracking-wide text-muted-foreground">
                  <th className="py-2 pr-4">Order</th>
                  <th className="py-2 pr-4">Created</th>
                  <th className="py-2 pr-4">Status</th>
                  <th className="py-2 pr-4">Total</th>
                  <th className="py-2 pr-4">Payment</th>
                  <th className="py-2 pr-4">Actions</th>
                </tr>
              </thead>
              <tbody>
                {orders.map((order) => {
                  const payment = order.payment;
                  const formattedTotal = formatCurrency(order.amount_total, order.currency);
                  return (
                    <tr key={order.id} className="border-b border-border/20 align-top">
                      <td className="py-3 pr-4 font-mono text-xs">
                        <div>{order.id}</div>
                        <Link className="text-xs text-primary underline" href={`/admin/orders/${order.id}`}>
                          View details
                        </Link>
                      </td>
                      <td className="py-3 pr-4 text-sm">
                        {new Date(order.created_at).toLocaleString()}
                      </td>
                      <td className="py-3 pr-4 text-sm">
                        <StatusBadge status={order.status} />
                        {order.payment_status ? (
                          <div className="text-xs text-muted-foreground">Payment: {order.payment_status}</div>
                        ) : null}
                      </td>
                      <td className="py-3 pr-4 text-sm">{formattedTotal}</td>
                      <td className="py-3 pr-4 text-xs">
                        {payment ? (
                          <div className="space-y-1">
                            <div className="font-mono">{payment.id}</div>
                            <div className="text-sm">
                              <span className="text-muted-foreground">{payment.status}</span>
                              {" | "}
                              {formatCurrency(Number(payment.amount || 0), payment.currency || order.currency)}
                            </div>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </td>
                      <td className="py-3 pr-4">
                        <div className="flex flex-wrap gap-2">
                          <Button
                            variant="soft"
                            className="h-9 min-h-0 px-3 text-xs"
                            onClick={async () => {
                              try {
                                const result = await callPayments(
                                  "/create",
                                  { order_id: order.id },
                                  token,
                                );
                                toast(`Payment created: ${result.payment_id ?? "ok"}`, {
                                  variant: "success",
                                });
                                const refreshed = await supabase
                                  .from("payments")
                                  .select("id,order_id,status,amount,created_at,currency")
                                  .eq("order_id", order.id)
                                  .order("created_at", { ascending: false })
                                  .limit(1)
                                  .maybeSingle();
                                const refreshedData = refreshed.data;
                                if (!refreshed.error && refreshedData) {
                                  setOrders((prev) =>
                                    prev.map((item) =>
                                      item.id === order.id
                                        ? {
                                            ...item,
                                            payment: {
                                              id: refreshedData.id,
                                              status: refreshedData.status,
                                              amount: Number(refreshedData.amount || 0),
                                              currency: refreshedData.currency ?? order.currency,
                                              created_at: refreshedData.created_at,
                                            },
                                          }
                                        : item,
                                    ),
                                  );
                                }
                                handleRefresh();
                              } catch (err) {
                                toast(err instanceof Error ? err.message : String(err), {
                                  variant: "error",
                                });
                              }
                            }}
                          >
                            Create payment
                          </Button>
                          {payment ? (
                            <>
                              <Button
                                variant="soft"
                                className="h-9 min-h-0 px-3 text-xs"
                                onClick={async () => {
                                  try {
                                    await callPayments(
                                      "/webhook",
                                      { payment_id: payment.id, status: "succeeded" },
                                      token,
                                    );
                                    setOrders((prev) =>
                                      prev.map((item) =>
                                        item.id === order.id
                                          ? {
                                              ...item,
                                              payment: {
                                                ...(item.payment as Payment),
                                                status: "succeeded",
                                              },
                                            }
                                          : item,
                                      ),
                                    );
                                    handleRefresh();
                                  } catch (err) {
                                    toast(err instanceof Error ? err.message : String(err), {
                                      variant: "error",
                                    });
                                  }
                                }}
                              >
                                Mark succeeded
                              </Button>
                              <Button
                                variant="soft"
                                className="h-9 min-h-0 px-3 text-xs"
                                onClick={async () => {
                                  try {
                                    await callPayments(
                                      "/webhook",
                                      { payment_id: payment.id, status: "failed" },
                                      token,
                                    );
                                    setOrders((prev) =>
                                      prev.map((item) =>
                                        item.id === order.id
                                          ? {
                                              ...item,
                                              payment: {
                                                ...(item.payment as Payment),
                                                status: "failed",
                                              },
                                            }
                                          : item,
                                      ),
                                    );
                                    handleRefresh();
                                  } catch (err) {
                                    toast(err instanceof Error ? err.message : String(err), {
                                      variant: "error",
                                    });
                                  }
                                }}
                              >
                                Mark failed
                              </Button>
                            </>
                          ) : null}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
            <div>
              Showing {orders.length} of {total.toLocaleString()} orders
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                className="h-8 px-3"
                disabled={page <= 1}
                onClick={() => setPage((value) => Math.max(1, value - 1))}
              >
                Previous
              </Button>
              <span>
                Page {page} of {totalPages.toLocaleString()}
              </span>
              <Button
                variant="ghost"
                className="h-8 px-3"
                disabled={page >= totalPages}
                onClick={() => setPage((value) => Math.min(totalPages, value + 1))}
              >
                Next
              </Button>
            </div>
          </div>
        </div>
      )}
    </Section>
  );
}

import { NextResponse } from "next/server";
import { requireAdmin } from "@/utils/auth/guard";
import { getAdminClient } from "@/utils/supabase/admin";
import { normalizeSku } from "@shared/lib/normalize";

const DEFAULT_BUCKET = "product-images";
const allowedExt = new Set(["webp", "png", "jpg", "jpeg", "avif"]);

function resolveExt(input?: string | null): string {
  if (typeof input !== "string" || !input.trim()) return "webp";
  let ext = input.trim().toLowerCase();
  if (ext.includes("/")) {
    const [, subtype] = ext.split("/");
    if (subtype) ext = subtype;
  }
  ext = ext.replace(/[^a-z0-9]/g, "");
  if (ext === "jpeg") ext = "jpg";
  if (!allowedExt.has(ext)) return "webp";
  return ext;
}

function toAbsoluteUrl(base: string, path: string): string {
  if (/^https?:/i.test(path)) return path;
  const normalizedBase = base.replace(/\/$/, "");
  if (!path.startsWith("/")) {
    return `${normalizedBase}/${path}`;
  }
  return `${normalizedBase}${path}`;
}

function encodeObjectPath(path: string): string {
  return path
    .split("/")
    .filter(Boolean)
    .map(encodeURIComponent)
    .join("/");
}

function getSupabaseUrl(): string {
  const candidates = [
    process.env.SUPABASE_URL,
    process.env.NEXT_PUBLIC_SUPABASE_URL,
    process.env.VITE_SUPABASE_URL,
  ];
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim();
    }
  }
  throw new Error("SUPABASE_URL is not configured");
}

function jsonError(status: number, code: string, message: string) {
  return NextResponse.json(
    { error: code, message },
    { status, headers: { "cache-control": "no-store" } }
  );
}

export async function POST(request: Request) {
  const auth = await requireAdmin(request);
  if ("response" in auth) return auth.response;

  const supabaseUrl = (() => {
    try {
      return getSupabaseUrl();
    } catch (error: any) {
      throw new Error(error?.message ?? "SUPABASE_URL is not configured");
    }
  })();
  const bucket = process.env.SUPABASE_PRODUCT_BUCKET?.trim() || DEFAULT_BUCKET;

  let payload: Record<string, unknown>;
  try {
    payload = await request.json();
  } catch {
    return jsonError(400, "bad_json", "Invalid JSON body");
  }

  const productId = typeof payload?.productId === "string" ? payload.productId.trim() : "";
  const skuRaw = typeof payload?.sku === "string" ? payload.sku.trim() : "";
  const slugRaw = typeof payload?.slug === "string" ? payload.slug.trim() : "";

  if (!productId && !skuRaw && !slugRaw) {
    return jsonError(400, "bad_request", "productId and/or sku required");
  }

  const extHint = typeof payload?.ext === "string" ? payload.ext : undefined;
  const ext = resolveExt(extHint);
  const normalizedSku = normalizeSku(skuRaw || slugRaw || productId);
  const safeFolder = normalizedSku
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-+|-+$/g, "") || "product";
  const timestamp = Date.now();
  const random = Math.random().toString(36).slice(2, 8);
  const objectPath = `${safeFolder}/main-${timestamp}-${random}.${ext}`;

  try {
    const supabase = getAdminClient();
    const storage = supabase.storage.from(bucket);
    const { data, error } = await storage.createSignedUploadUrl(objectPath, { upsert: true });
    if (error || !data?.signedUrl) {
      throw error ?? new Error("Failed to create signed upload url");
    }

    try {
      let updated = 0;
      if (skuRaw) {
        const { data: rows, error: updateErr } = await supabase
          .from("shop.products")
          .update({ image_path: objectPath })
          .eq("sku", skuRaw)
          .select("id");
        if (updateErr) throw updateErr;
        updated = rows?.length ?? 0;
      }
      if (!updated && slugRaw) {
        const { data: rows, error: updateErr } = await supabase
          .from("shop.products")
          .update({ image_path: objectPath })
          .eq("slug", slugRaw)
          .select("id");
        if (updateErr) throw updateErr;
        updated = rows?.length ?? 0;
      }
      if (!updated && productId) {
        const { data: rows, error: updateErr } = await supabase
          .from("shop.products")
          .update({ image_path: objectPath })
          .eq("id", productId)
          .select("id");
        if (updateErr) throw updateErr;
      }
    } catch (updateErr) {
      console.warn("admin-get-upload-url: failed to update shop.products", updateErr);
    }

    const uploadUrl = toAbsoluteUrl(supabaseUrl, data.signedUrl ?? "");
    const publicUrl = `${supabaseUrl.replace(/\/$/, "")}/storage/v1/object/public/${encodeURIComponent(bucket)}/${encodeObjectPath(objectPath)}`;

    return NextResponse.json(
      {
        ok: true,
        uploadUrl,
        token: data.token,
        path: objectPath,
        publicUrl,
        bucket,
      },
      { status: 200, headers: { "cache-control": "no-store" } }
    );
  } catch (error: any) {
    return jsonError(500, "upload_url_error", error?.message ?? "upload url error");
  }
}

