  return NextResponse.json(
    { error: "method_not_allowed" },
    { status: 405, headers: { Allow: "POST" } }
  );
}

import { json } from "../../orders/utils";
import { requireAdmin } from "@/utils/auth/guard";
import { getAdminClient } from "@/utils/supabase/admin";

const DAY_MS = 86_400_000;
const MAX_ROWS = 5_000;

function parseRange(search: URLSearchParams) {
  const rangeRaw = (search.get("range") ?? "30").toLowerCase();
  const now = new Date();
  const to = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 23, 59, 59, 999));

  if (rangeRaw === "custom") {
    const fromParam = search.get("from");
    const toParam = search.get("to");
    if (fromParam && toParam) {
      const fromDate = new Date(fromParam);
      const toDate = new Date(toParam);
      if (!Number.isNaN(fromDate.getTime()) && !Number.isNaN(toDate.getTime())) {
        const from = new Date(Date.UTC(fromDate.getUTCFullYear(), fromDate.getUTCMonth(), fromDate.getUTCDate(), 0, 0, 0, 0));
        const toCustom = new Date(Date.UTC(toDate.getUTCFullYear(), toDate.getUTCMonth(), toDate.getUTCDate(), 23, 59, 59, 999));
        if (from <= toCustom) {
          return { from, to: toCustom };
        }
      }
    }
  }

  const days = Number.parseInt(rangeRaw, 10);
  const validDays = Number.isFinite(days) && days > 0 ? Math.min(days, 180) : 30;
  const from = new Date(to.getTime() - validDays * DAY_MS);
  from.setUTCHours(0, 0, 0, 0);
  return { from, to };
}

function dateKey(value: string | null | undefined): string | null {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString().slice(0, 10);
}

function safeSlug(slug: unknown): string {
  if (typeof slug !== "string") return "-";
  const trimmed = slug.trim();
  return trimmed || "-";
}

function toNumber(value: unknown): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
}

function normalizeSource(row: any): string {
  const params = (row?.params ?? {}) as Record<string, unknown>;
  const source = typeof params?.utm_source === "string" ? params.utm_source.trim() : "";
  if (source) return source;
  const referrer = typeof row?.referrer === "string" ? row.referrer.trim() : "";
  return referrer || "-";
}

function normalizeCampaign(row: any): string {
  const params = (row?.params ?? {}) as Record<string, unknown>;
  const campaign = typeof params?.utm_campaign === "string" ? params.utm_campaign.trim() : "";
  return campaign || "-";
}

export async function GET(request: Request) {
  const auth = await requireAdmin(request);
  if ("response" in auth) return auth.response;

  const supabase = getAdminClient();
  const url = new URL(request.url);
  const { from, to } = parseRange(url.searchParams);

  try {
    const [clicksRes, impressionsRes] = await Promise.all([
      supabase
        .from("clicks")
        .select("ts, slug, referrer, params")
        .gte("ts", from.toISOString())
        .lte("ts", to.toISOString())
        .order("ts", { ascending: false })
        .limit(MAX_ROWS),
      supabase
        .from("impressions")
        .select("ts, slug, device, lang")
        .gte("ts", from.toISOString())
        .lte("ts", to.toISOString())
        .order("ts", { ascending: false })
        .limit(MAX_ROWS),
    ]);

    if (clicksRes.error) {
      return json({ ok: false, code: "db_clicks", message: clicksRes.error.message }, 500);
    }
    if (impressionsRes.error) {
      return json({ ok: false, code: "db_impressions", message: impressionsRes.error.message }, 500);
    }

    const clicks = (clicksRes.data ?? []) as Array<Record<string, any>>;
    const impressions = (impressionsRes.data ?? []) as Array<Record<string, any>>;

    const clicksByDayMap = new Map<string, number>();
    const impressionsByDayMap = new Map<string, number>();
    const slugClicks = new Map<string, number>();
    const slugImpressions = new Map<string, number>();
    const slugSparks = new Map<string, Map<string, number>>();
    const sourcesMap = new Map<string, number>();
    const utmMap = new Map<string, number>();
    const deviceMap = new Map<string, number>();
    const langMap = new Map<string, number>();

    for (const row of clicks) {
      const day = dateKey(row.ts);
      if (!day) continue;
      clicksByDayMap.set(day, (clicksByDayMap.get(day) ?? 0) + 1);

      const slug = safeSlug(row.slug);
      slugClicks.set(slug, (slugClicks.get(slug) ?? 0) + 1);

      if (!slugSparks.has(slug)) slugSparks.set(slug, new Map());
      const sparkMap = slugSparks.get(slug)!;
      sparkMap.set(day, (sparkMap.get(day) ?? 0) + 1);

      const sourceKey = normalizeSource(row);
      sourcesMap.set(sourceKey, (sourcesMap.get(sourceKey) ?? 0) + 1);

      const utmKey = `${normalizeSource(row)}|${normalizeCampaign(row)}`;
      utmMap.set(utmKey, (utmMap.get(utmKey) ?? 0) + 1);
    }

    for (const row of impressions) {
      const day = dateKey(row.ts);
      if (day) {
        impressionsByDayMap.set(day, (impressionsByDayMap.get(day) ?? 0) + 1);
      }
      const slug = safeSlug(row.slug);
      slugImpressions.set(slug, (slugImpressions.get(slug) ?? 0) + 1);

      const device = typeof row?.device === "string" && row.device.trim() ? row.device.trim() : "unknown";
      deviceMap.set(device, (deviceMap.get(device) ?? 0) + 1);
      const lang = typeof row?.lang === "string" && row.lang.trim() ? row.lang.trim() : "-";
      langMap.set(lang, (langMap.get(lang) ?? 0) + 1);
    }

    const clicksByDay = Array.from(clicksByDayMap.entries())
      .map(([date, count]) => ({ date, count }))
      .sort((a, b) => a.date.localeCompare(b.date));
    const impressionsByDay = Array.from(impressionsByDayMap.entries())
      .map(([date, count]) => ({ date, count }))
      .sort((a, b) => a.date.localeCompare(b.date));

    const topSlugs = Array.from(slugClicks.entries())
      .map(([slug, clicksCount]) => {
        const imp = slugImpressions.get(slug) ?? 0;
        const ctr = imp > 0 ? clicksCount / imp : 0;
        return { slug, clicks: clicksCount, impressions: imp, ctr };
      })
      .sort((a, b) => b.clicks - a.clicks)
      .slice(0, 50);

    const sparkline = Object.fromEntries(
      topSlugs.slice(0, 10).map(({ slug }) => {
        const map = slugSparks.get(slug) ?? new Map<string, number>();
        const data = Array.from(map.entries())
          .map(([date, count]) => ({ date, count }))
          .sort((a, b) => a.date.localeCompare(b.date));
        return [slug, data];
      }),
    );

    const topSources = Array.from(sourcesMap.entries())
      .map(([source, count]) => ({ source, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 20);

    const utmReport = Array.from(utmMap.entries())
      .map(([key, count]) => {
        const [source, campaign] = key.split("|");
        return { source, campaign, count };
      })
      .sort((a, b) => b.count - a.count)
      .slice(0, 50);

    const devices = Array.from(deviceMap.entries())
      .map(([device, count]) => ({ device, count }))
      .sort((a, b) => b.count - a.count);

    const languages = Array.from(langMap.entries())
      .map(([lang, count]) => ({ lang, count }))
      .sort((a, b) => b.count - a.count);

    return json({
      ok: true,
      range: {
        from: from.toISOString(),
        to: to.toISOString(),
      },
      totals: {
        clicks: clicks.length,
        impressions: impressions.length,
      },
      byDay: {
        clicks: clicksByDay,
        impressions: impressionsByDay,
      },
      topSlugs,
      sparkline,
      topSources,
      utm: utmReport,
      devices,
      languages,
      meta: {
        limit: MAX_ROWS,
        generatedAt: new Date().toISOString(),
      },
    });
  } catch (error: unknown) {
    return json(
      {
        ok: false,
        code: "internal",
        message: String((error as Error)?.message ?? error),
      },
      500,
    );
  }
}

import { NextResponse } from "next/server";

import { requireAdmin } from "@/utils/auth/guard";
import { getAdminClient } from "@/utils/supabase/admin";

interface OrderRow {
  created_at: string;
  amount_total: number | string | null;
  amount_discounts: number | string | null;
  amount_tax: number | string | null;
  status: string | null;
  payment_status: string | null;
}

interface MonthBucket {
  key: string;
  label: string;
}

const MONTHLY_GOAL = 20000;
const MONTH_COUNT = 12;
const DAY_MS = 86_400_000;

function toNumber(value: number | string | null | undefined): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
}

function buildMonthBuckets(reference: Date): MonthBucket[] {
  const buckets: MonthBucket[] = [];
  for (let index = MONTH_COUNT - 1; index >= 0; index -= 1) {
    const date = new Date(Date.UTC(reference.getUTCFullYear(), reference.getUTCMonth() - index, 1));
    const key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`;
    buckets.push({
      key,
      label: date.toLocaleString(undefined, { month: "short" }),
    });
  }
  return buckets;
}

function buildDailyBuckets(reference: Date): Array<{ key: string; label: string }> {
  const buckets: Array<{ key: string; label: string }> = [];
  for (let offset = 6; offset >= 0; offset -= 1) {
    const date = new Date(Date.UTC(reference.getUTCFullYear(), reference.getUTCMonth(), reference.getUTCDate() - offset));
    const key = date.toISOString().slice(0, 10);
    buckets.push({ key, label: date.toLocaleDateString(undefined, { month: "short", day: "numeric" }) });
  }
  return buckets;
}

export async function GET(request: Request) {
  const auth = await requireAdmin(request);
  if ("response" in auth) return auth.response;

  try {
    const supabase = getAdminClient();
    const now = new Date();
    const monthBuckets = buildMonthBuckets(now);
    const earliestMonth = monthBuckets[0];
    const monthMap = new Map<string, { sales: number; expenses: number }>();
    monthBuckets.forEach((bucket) => {
      monthMap.set(bucket.key, { sales: 0, expenses: 0 });
    });

    const dailyBuckets = buildDailyBuckets(now);
    const dailyMap = new Map<string, number>();
    dailyBuckets.forEach((bucket) => dailyMap.set(bucket.key, 0));

    const startMonthIso = `${earliestMonth.key}-01T00:00:00.000Z`;

    const { data, error } = await supabase
      .from("order_v2")
      .select("created_at, amount_total, amount_discounts, amount_tax, status, payment_status")
      .gte("created_at", startMonthIso);

    if (error) {
      return NextResponse.json(
        { ok: false, error: "db", message: error.message },
        { status: 500, headers: { "cache-control": "no-store" } },
      );
    }

    const orders: OrderRow[] = Array.isArray(data) ? (data as OrderRow[]) : [];

    let cash = 0;
    let forecast = 0;
    let succeededLast7 = 0;
    let succeededPrevious7 = 0;
    let pendingCount = 0;
    let processingCount = 0;
    let succeededCount = 0;

    const nowMs = now.getTime();
    const sevenDaysAgoMs = nowMs - DAY_MS * 6;
    const thirtyDaysAgoMs = nowMs - DAY_MS * 29;

    const fourteenDaysAgoMs = nowMs - DAY_MS * 13;

    for (const row of orders) {
      const createdAt = row.created_at ? new Date(row.created_at) : null;
      if (!createdAt || Number.isNaN(createdAt.getTime())) continue;

      const amountTotal = toNumber(row.amount_total);
      const expenseValue = toNumber(row.amount_discounts) + toNumber(row.amount_tax);
      const status = (row.status || "").toLowerCase();
      const monthKey = `${createdAt.getUTCFullYear()}-${String(createdAt.getUTCMonth() + 1).padStart(2, "0")}`;
      const bucket = monthMap.get(monthKey);
      if (bucket) {
        if (status === "succeeded") {
          bucket.sales += amountTotal;
          bucket.expenses += expenseValue;
        } else if (status === "failed" || status === "cancelled" || status === "refunded") {
          bucket.expenses += expenseValue;
        }
      }

      const createdMs = createdAt.getTime();
      const dayKey = createdAt.toISOString().slice(0, 10);
      if (dailyMap.has(dayKey) && status === "succeeded") {
        dailyMap.set(dayKey, (dailyMap.get(dayKey) || 0) + amountTotal);
      }

      if (status === "pending") pendingCount += 1;
      if (status === "processing") processingCount += 1;
      if (status === "succeeded") succeededCount += 1;

      if (status === "succeeded" && createdMs >= sevenDaysAgoMs) {
        cash += amountTotal;
      }

      if ((status === "pending" || status === "processing") && createdMs >= nowMs - DAY_MS * 30) {
        forecast += amountTotal;
      }

      if (status === "succeeded") {
        if (createdMs >= sevenDaysAgoMs) {
          succeededLast7 += amountTotal;
        } else if (createdMs >= fourteenDaysAgoMs) {
          succeededPrevious7 += amountTotal;
        }
      }
    }

    const currentMonthKey = monthBuckets[monthBuckets.length - 1]?.key;
    const currentMonthSales = currentMonthKey ? (monthMap.get(currentMonthKey)?.sales ?? 0) : 0;
    const goalPct = MONTHLY_GOAL > 0 ? Math.min(100, Math.round((currentMonthSales / MONTHLY_GOAL) * 100)) : 0;
    const productivityPct = (() => {
      if (succeededPrevious7 <= 0 && succeededLast7 <= 0) return 0;
      if (succeededPrevious7 <= 0) return 100;
      const ratio = (succeededLast7 / succeededPrevious7) * 100;
      return Math.max(0, Math.min(200, Math.round(ratio)));
    })();

    const cashflow = dailyBuckets.map(({ key, label }) => ({
      label,
      value: Math.round(dailyMap.get(key) || 0),
    }));

    const sales = monthBuckets.map(({ key, label }) => ({
      label,
      value: Math.round(monthMap.get(key)?.sales ?? 0),
    }));
    const expenses = monthBuckets.map(({ key, label }) => ({
      label,
      value: Math.round(monthMap.get(key)?.expenses ?? 0),
    }));
    const profit = monthBuckets.map(({ key, label }) => {
      const totals = monthMap.get(key) ?? { sales: 0, expenses: 0 };
      return {
        label,
        value: Math.max(0, Math.round(totals.sales - totals.expenses)),
      };
    });

    return NextResponse.json(
      {
        ok: true,
        metrics: {
          kpis: {
            cash: Math.round(cash),
            cashflowForecast: Math.round(forecast),
            goalPct,
            cards: {
              pending: pendingCount,
              inProgress: processingCount,
              done: succeededCount,
            },
            productivityPct,
          },
          sales,
          expenses,
          profit,
          cashflow,
          updatedAt: new Date().toISOString(),
        },
      },
      { headers: { "cache-control": "no-store" } },
    );
  } catch (error: unknown) {
    return NextResponse.json(
      { ok: false, error: "internal", message: String((error as Error)?.message ?? error) },
      { status: 500, headers: { "cache-control": "no-store" } },
    );
  }
}

import { NextResponse } from "next/server";

import { requireAuth } from "@/utils/auth/guard";
import { getAdminClient } from "@/utils/supabase/admin";

type OrderItemInput = { id?: string; qty?: number };

type CheckoutContact = {
  fullName?: string;
  email?: string;
};

type CheckoutShipping = {
  address?: string;
  city?: string;
  postalCode?: string;
  notes?: string;
};

type CheckoutPayload = {
  contact?: CheckoutContact;
  shipping?: CheckoutShipping;
};

type OrderPayload = {
  items?: OrderItemInput[];
  currency?: string;
  checkout?: CheckoutPayload | null;
};

function json(body: unknown, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "cache-control": "no-store" },
  });
}

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

function parsePayload(body: unknown): OrderPayload {
  if (!body || typeof body !== "object") return {};
  return body as OrderPayload;
}

function normalizeField(value: unknown, max = 512): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  if (trimmed.length > max) return trimmed.slice(0, max);
  return trimmed;
}

function extractCheckout(raw: unknown): CheckoutPayload | null {
  if (!raw || typeof raw !== "object") return null;
  const source = raw as CheckoutPayload;
  const contactRaw = source.contact || {};
  const shippingRaw = source.shipping || {};
  const contact: CheckoutContact = {};
  const shipping: CheckoutShipping = {};

  const name = normalizeField((contactRaw as CheckoutContact).fullName, 160);
  if (name) contact.fullName = name;
  const email = normalizeField((contactRaw as CheckoutContact).email, 254);
  if (email) contact.email = email;

  const address = normalizeField((shippingRaw as CheckoutShipping).address);
  if (address) shipping.address = address;
  const city = normalizeField((shippingRaw as CheckoutShipping).city, 120);
  if (city) shipping.city = city;
  const postal = normalizeField((shippingRaw as CheckoutShipping).postalCode, 40);
  if (postal) shipping.postalCode = postal;
  const notes = normalizeField((shippingRaw as CheckoutShipping).notes, 500);
  if (notes) shipping.notes = notes;

  const hasContact = Object.keys(contact).length > 0;
  const hasShipping = Object.keys(shipping).length > 0;
  if (!hasContact && !hasShipping) return null;

  const result: CheckoutPayload = {};
  if (hasContact) result.contact = contact;
  if (hasShipping) result.shipping = shipping;
  return result;
}

export async function POST(request: Request) {
  // Пытаемся определить пользователя, но не блокируем гостевой чекаут
  let userId: string | null = null;
  try {
    const maybeAuth = await requireAuth(request);
    if (!("response" in maybeAuth)) {
      userId = maybeAuth.user.id;
    }
  } catch {}

  const supabase = getAdminClient();

  try {
    try {
      const orphanCheck = await supabase
        .from("orders")
        .select("id", { count: "exact", head: true })
        .is("user_id", null);
      if (!orphanCheck.error && (orphanCheck.count ?? 0) > 0) {
        console.warn("orders-create", {
          warning: "orphan_orders_detected",
          count: orphanCheck.count,
        });
      }
    } catch (orphanError) {
      console.warn("orders-create orphan check failed", orphanError);
    }

    const payload = parsePayload(await request.json().catch(() => ({})));
    const rawItems = Array.isArray(payload.items) ? payload.items : [];
    const items = rawItems
      .filter((item): item is { id: string; qty?: number } => Boolean(item && item.id))
      .map((item) => ({ id: String(item.id), qty: Math.max(1, Number(item.qty ?? 1)) }))
      .filter((item) => isUuid(item.id));

    const currency =
      typeof payload.currency === "string" && payload.currency.trim()
        ? payload.currency.trim()
        : undefined;
    const checkoutMeta = extractCheckout(payload.checkout ?? null);

    let rpcResponse;
    if (items.length) {
      rpcResponse = await supabase.rpc("place_order_with_items", {
        p_user_id: userId,
        p_items: items,
        p_currency: currency,
      });
    } else {
      rpcResponse = await supabase.rpc("place_order", { p_user_id: userId });
    }

    if (rpcResponse.error) {
      console.error("orders-create", rpcResponse.error);
      if (
        rpcResponse.error.code === "23503" &&
        typeof rpcResponse.error.message === "string" &&
        rpcResponse.error.message.includes("orders_user_id_fkey")
      ) {
        return json({ ok: false, code: "user_not_found", message: "User record missing" }, 409);
      }
      return json({ ok: false, code: "db", message: "Database error" }, 500);
    }

    const orderId = typeof rpcResponse.data === "string" && rpcResponse.data ? rpcResponse.data : null;

    if (checkoutMeta && orderId) {
      const { error } = await supabase
        .from("orders")
        .update({ checkout_metadata: checkoutMeta })
        .eq("id", orderId);
      if (error) {
        console.warn("orders-create checkout metadata", error);
      }
    }

    return json({ ok: true, order_id: orderId || rpcResponse.data }, 200);
  } catch (error: any) {
    console.error("orders-create", error);
    return json({ ok: false, code: "internal", message: String(error?.message ?? error) }, 500);
  }
}

