    ];
  }, [favOffers, origin, t]);

  const title =
    (t("nav.favorites") || "Favorites") + " - " + (t("favorites.savedSubtitle") || "your saved offers");
  const description = t("favorites.description") || "Quick access to your saved offers.";

  return (
    <>
  <script
    id="favorites-jsonld"
