    {/* остальное */}


        <h1 className="mb-4 text-3xl font-semibold tracking-tight sm:text-4xl">
          {t("nav.favorites") || "Favorites"}
        </h1>

        {favOffers.length > 0 && (
          <SectionCard
            actions={
              <>
                <ButtonGhost onClick={clearAll}>
